  streams: {
    stream_antigravity_01: {
      messages: [
        { role: 'user', content: 'Initiate system checks.' },
        { role: 'agent', content: 'Antigravity core online. Ready to execute.' }
      ]
    }
  }
};

export default function App() {
  // Your UI specification tree containing the snippet from Step 3
  const uiSpec = getAntigravityChatSpec(); 

  return (
    <JSONUIProvider registry={registry} initialState={layoutState}>
      <Renderer spec={uiSpec} />
    </JSONUIProvider>
  );
}
