2. Implement the Self-Arranging Layout Wrapper
The dashboard wrapper coordinates real-time collision resolution. When a user modifies or inserts a tile, the inner engine automatically pushes lower components downward along the Y-axis ("vertical gravity compacting").
typescript
export function SelfArrangingDashboard() {
  const [tiles, setTiles] = useState<DashboardTile[]>(INITIAL_TILES);

  // Sync state changes instantly when layout rearrangement completes
  const handleLayoutChange = (newLayout: GridLayout.Layout[]) => {
    setTiles((currentTiles) =>
      currentTiles.map((tile) => {
        const layoutItem = newLayout.find((item) => item.i === tile.id);
        return layoutItem
          ? { ...tile, x: layoutItem.x, y: layoutItem.y, w: layoutItem.w, h: layoutItem.h }
          : tile;
      })
    );
  };

  // Automatically insert a new tile onto the first available grid space
  const addTile = () => {
    const nextId = (tiles.length + 1).toString();
    const newTile: DashboardTile = {
      id: nextId,
      title: `Widget ${nextId}`,
      x: (tiles.length * 4) % 12, // Auto-distribute horizontally across a 12-column grid
      y: Infinity,               // "Infinity" forces the tile to arrange itself at the very bottom
      w: 4,
      h: 2,
      content: '⚡ Newly initialized sandbox card.'
    };
    setTiles([...tiles, newTile]);
  };

  // Convert application internal state into grid layouts
  const currentLayout = tiles.map((tile) => ({
    i: tile.id,
    x: tile.x,
    y: tile.y,
    w: tile.w,
    h: tile.h,
    minW: 2,
    minH: 2
  }));

  return (
    <div className="min-h-screen bg-zinc-950 p-6 text-zinc-100">
      <header className="flex justify-between items-center mb-6 border-b border-zinc-800 pb-4">
        <div>
          <h1 className="text-xl font-bold tracking-tight">Dynamic Grid Workspace</h1>
          <p className="text-xs text-zinc-400">Self-compacting layout canvas engine</p>
        </div>
        <button
          onClick={addTile}
          className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded text-xs font-medium transition-colors"
        >
          + Add Tile
        </button>
      </header>

      {/* Grid container with 12 structural responsive subdivisions */}
      <GridLayout
        className="layout"
        layout={currentLayout}
        cols={12}
        rowHeight={80}
        width={1200}
        onLayoutChange={handleLayoutChange}
        isDraggable={true}
        isResizable={true}
        compactType="vertical" // Force elements to float upward into vacant grid cavities
        margin={[16, 16]}      // Gaps between viewport grid modules [X, Y] px
      >
        {tiles.map((tile) => (
          <div
            key={tile.id}
            className="bg-zinc-900 border border-zinc-800 rounded-xl shadow-lg flex flex-col overflow-hidden cursor-grab active:cursor-grabbing select-none"
          >
            {/* Tile Header Drag Anchor Area */}
            <div className="bg-zinc-900 px-4 py-2.5 border-b border-zinc-800 flex justify-between items-center text-xs font-semibold text-zinc-300">
              <span>{tile.title}</span>
              <span className="text-[10px] text-zinc-500 font-mono">ID: {tile.id}</span>
            </div>

            {/* Inner Dashboard Component Node Content View */}
            <div className="p-4 flex-1 text-sm text-zinc-400 bg-zinc-950/20">
              {tile.content}
            </div>
          </div>
        ))}
      </GridLayout>
    </div>
  );
}
