// app/api/ui-stream/route.ts
import { openai } from '@ai-sdk/openai';
import { streamText } from 'ai';
import { myCatalog } from '@/components/catalog';

export async function POST(req: Request) {
  const { prompt } = await req.json();

  // Convert the catalog schemas into a clear format for the LLM prompt
  const catalogDefinition = JSON.stringify(myCatalog.components, null, 2);

  const systemInstructions = `
    You are a UI generation engine. You must output layout JSON matching the requested design.

    CRITICAL CONSTRAINT: You can ONLY use the component types declared in this catalog:
    ${catalogDefinition}

    Your output must exclusively be a sequence of valid JSON Patch operations in JSONL format. 
    Do not wrap the output in markdown block flags.

    Example output lines:
    {"op": "add", "path": "/root", "value": { "type": "AntigravityChatContainer", "props": { "streamId": "ag_1" } }}
    {"op": "add", "path": "/root/children/0", "value": { "type": "StreamButton", "props": { "label": "Engage" } }}
  `;

  const response = await streamText({
    model: openai('gpt-4o'),
    system: systemInstructions,
    prompt: prompt,
  });

  return response.toDataStreamResponse();
}
