/**
 * TypeScript mirror of `op-state-store/src/subid_ui.rs`.
 *
 * Types only — no logic. The Rust side is authoritative; this file exists so
 * the spec generator can work with the same type vocabulary.
 */

/**
 * The seven OSCAL subid categories from docs/subid-taxonomy.md.
 */
export const SUBID_CATEGORIES = ["src", "prj", "sch", "mut", "obs", "evt", "exp"] as const;
export type SubidCategory = (typeof SUBID_CATEGORIES)[number];

/**
 * Presentation roles — data-semantic only (no json-render component names).
 *
 * These are the kebab-case strings from `UiRole::as_str()` in Rust.
 */
export const UI_ROLES = [
  "surface",
  "display-value",
  "state-flag",
  "collection-view",
  "record-view",
  "value-list",
  "binary-control",
  "text-control",
  "numeric-control",
  "multi-choice",
  "editable-collection",
  "record-editor",
  "structured-control",
  "validation-carrier",
  "hydration-source",
  "trigger-binding",
  "repeat-binding",
] as const;

export type UiRole = (typeof UI_ROLES)[number];

/**
 * Normalized field shape used to refine obs/mut roles.
 * Derived from schema field types when available.
 */
export type UiFieldShape =
  | "boolean"
  | "string"
  | "integer"
  | "float"
  | "list-scalar"
  | "list-record"
  | "record"
  | "any";

/**
 * One populated catalog row for dump / API.
 * Mirrors `UiSubidProjection` in Rust.
 *
 * Returned by `GET /api/ui-model/plugin-schema/:plugin` in the `ui_projection` field.
 */
export interface UiSubidProjection {
  /** Plugin that owns this projection. */
  plugin_id: string;
  /** "field" | "method" | "schema" */
  kind: string;
  /** Field or method name. */
  id: string;
  /** Full subid string, e.g. "obs.software.plugin.xray.status@v1" */
  subid: string;
  /** Category extracted from subid (obs, mut, exp, ...) */
  category: SubidCategory | string;
  /** Presentation role (display-value, state-flag, ...) */
  role: UiRole;
  /** Unique join key = subid segments after category. */
  element_key: string;
}

/**
 * A plugin-owned UI surface route.
 * Mirrors `UiSurfaceRoute` in op-gallery-gen context.rs.
 */
export interface UiSurfaceRoute {
  /** Route path, e.g. "/antigravity/chat" */
  path: string;
  /** Human-readable name for nav */
  name?: string;
  /** Schema scope (which fields this surface shows) */
  schema?: string;
  /** Original raw object from the plugin */
  raw?: unknown;
}

/**
 * A plugin's ui_surfaces projection.
 * Mirrors `UiSurfaceProjection` in op-gallery-gen context.rs.
 */
export interface UiSurfaceProjection {
  /** Subids that declared ui_surfaces (for traceability) */
  subids: string[];
  /** Authoritative routes */
  routes: UiSurfaceRoute[];
  /** Where the routes came from ("default" | "example" | null) */
  value_source?: string;
}

/**
 * Check if a ui_surfaces projection is authoritative (has subids and routes).
 */
export function isAuthoritative(projection: UiSurfaceProjection | null | undefined): boolean {
  if (!projection) return false;
  return projection.subids.length > 0 && projection.routes.length > 0;
}

/**
 * Extract the category (first segment) from a subid.
 * Returns null if the category is not one of the seven known categories.
 */
export function subidCategory(subid: string): SubidCategory | null {
  const base = subid.split("@")[0] ?? subid;
  const cat = base.split(".")[0];
  if (cat && (SUBID_CATEGORIES as readonly string[]).includes(cat)) {
    return cat as SubidCategory;
  }
  return null;
}

/**
 * Derive a UiRole from a subid + optional field shape.
 * Mirrors `ui_role_from_subid` in Rust.
 */
export function uiRoleFromSubid(subid: string, shape?: UiFieldShape): UiRole | null {
  const cat = subidCategory(subid);
  if (!cat) return null;

  switch (cat) {
    case "exp":
      return "surface";
    case "sch":
      return "validation-carrier";
    case "src":
      return "hydration-source";
    case "evt":
      return "trigger-binding";
    case "prj":
      return "repeat-binding";
    case "obs":
      switch (shape) {
        case "boolean":
          return "state-flag";
        case "list-record":
          return "collection-view";
        case "record":
          return "record-view";
        case "list-scalar":
          return "value-list";
        default:
          return "display-value";
      }
    case "mut":
      switch (shape) {
        case "boolean":
          return "binary-control";
        case "string":
          return "text-control";
        case "integer":
        case "float":
          return "numeric-control";
        case "list-scalar":
          return "multi-choice";
        case "list-record":
          return "editable-collection";
        case "record":
          return "record-editor";
        default:
          return "structured-control";
      }
    default:
      return null;
  }
}

/**
 * Strip category from subid; remainder is the unique element key.
 * Mirrors `element_key_from_subid` in Rust.
 */
export function elementKeyFromSubid(subid: string): string {
  const [base, ver] = subid.split("@");
  const parts = (base ?? "").split(".");
  parts.shift(); // remove category
  const key = parts.join(".");
  if (ver && key) return `${key}@${ver}`;
  if (ver) return `@${ver}`;
  return key;
}

/**
 * Role-to-component mapping — the missing step.
 *
 * This is the sole point of contact between `UiRole` (semantics from
 * op-state-store/subid_ui.rs) and catalog component names (syntax from
 * catalog.ts). No other file may hardcode catalog component names based on
 * subid category.
 *
 * The mapping determines what component a generated spec may use for a given
 * projected field.
 */
import type { UiRole } from "@/lib/subid-ui";

/**
 * How a UiRole maps to a catalog component.
 */
export interface RoleMapping {
  /**
   * Primary catalog component type for this role.
   * Undefined when `omit` is true.
   */
  component?: string;

  /**
   * Props to merge in (static, not state-bound).
   * These are defaults that can be overridden by the spec generator.
   */
  staticProps?: Record<string, unknown>;

  /**
   * When true, the mapped element needs a `repeat` block for collections.
   */
  useRepeat?: boolean;

  /**
   * When true, the role produces no rendered element and is silently omitted.
   * Used for meta-roles like validation-carrier, hydration-source, etc.
   */
  omit?: boolean;

  /**
   * When true, the component is read-only in this phase.
   * Controls will be editable in a future phase.
   */
  readOnly?: boolean;
}

/**
 * The role-to-component map.
 *
 * Every UiRole must have an entry here. The generator uses this to decide
 * which catalog component to emit for a given field's role.
 *
 * Design notes:
 * - `surface` becomes a route, not a rendered element — it drives nav
 * - `display-value` → `stateValue` — shows a single bound value
 * - `state-flag` → `statusDot` — boolean as health indicator
 * - `collection-view` → `streamObject` with repeat — shows list of records
 * - `record-view` → `card` — shows a single record as grouped kv pairs
 * - `value-list` → `container` with repeat → `kv` — shows list of scalars
 * - `binary-control` → `pill` (read-only) — boolean toggle, read-only for now
 * - `text-control` → `stateValue` (read-only) — string input, read-only for now
 * - `numeric-control` → `statCard` — number input, read-only for now
 * - `multi-choice` → `stateValue` with raw format — enum/list selection
 * - `editable-collection` → `streamObject` with repeat — editable list of records
 * - `record-editor` → `card` (read-only) — editable record form
 * - `structured-control` → `card` (read-only) — complex nested structure
 * - validation-carrier, hydration-source, trigger-binding, repeat-binding → omitted
 */
export const ROLE_MAP: Record<UiRole, RoleMapping> = {
  // `exp.*` — consumer-facing surface → becomes a route, not an element
  "surface": {
    omit: true,
  },

  // `obs` scalar — read-only value
  "display-value": {
    component: "stateValue",
  },

  // `obs` boolean — on/off state
  "state-flag": {
    component: "statusDot",
    staticProps: { status: "ok" }, // overridden by $state binding at render
  },

  // `obs` list of records
  "collection-view": {
    component: "streamObject",
    useRepeat: true,
  },

  // `obs` record
  "record-view": {
    component: "card",
  },

  // `obs` list of scalars
  "value-list": {
    component: "container",
    useRepeat: true,
  },

  // `mut` boolean — read-only for now
  "binary-control": {
    component: "pill",
    staticProps: { tone: null },
    readOnly: true,
  },

  // `mut` string — read-only for now
  "text-control": {
    component: "stateValue",
    readOnly: true,
  },

  // `mut` integer / number
  "numeric-control": {
    component: "statCard",
    staticProps: { sub: null, variant: null, tone: null },
    readOnly: true,
  },

  // `mut` list of scalars
  "multi-choice": {
    component: "stateValue",
    staticProps: { format: "raw" },
    readOnly: true,
  },

  // `mut` list of records
  "editable-collection": {
    component: "streamObject",
    useRepeat: true,
    readOnly: true,
  },

  // `mut` record
  "record-editor": {
    component: "card",
    readOnly: true,
  },

  // `mut` otherwise / unstructured
  "structured-control": {
    component: "card",
    readOnly: true,
  },

  // `sch.*` — validation attaches to controls, not rendered directly
  "validation-carrier": {
    omit: true,
  },

  // `src.*` — hydration / ingress, not rendered directly
  "hydration-source": {
    omit: true,
  },

  // `evt.*` — trigger / audit binding, not rendered directly
  "trigger-binding": {
    omit: true,
  },

  // `prj.*` — projection / repeat binding, not rendered directly
  "repeat-binding": {
    omit: true,
  },
};

/**
 * Get the catalog component name for a UiRole.
 * Returns undefined if the role should be omitted.
 */
export function componentForRole(role: UiRole): string | undefined {
  const mapping = ROLE_MAP[role];
  if (mapping.omit) return undefined;
  return mapping.component;
}

/**
 * Check if a role should be omitted from generated specs.
 */
export function isOmittedRole(role: UiRole): boolean {
  return ROLE_MAP[role]?.omit === true;
}

/**
 * Check if a role is read-only in this phase.
 */
export function isReadOnlyRole(role: UiRole): boolean {
  return ROLE_MAP[role]?.readOnly === true;
}

/**
 * Check if a role needs a repeat block for collections.
 */
export function needsRepeat(role: UiRole): boolean {
  return ROLE_MAP[role]?.useRepeat === true;
}

/**
 * Get static props for a role, if any.
 */
export function staticPropsForRole(role: UiRole): Record<string, unknown> {
  return ROLE_MAP[role]?.staticProps ?? {};
}

/**
 * All UiRole values in a predictable order for iteration.
 */
export const ALL_UI_ROLES: UiRole[] = [
  "surface",
  "display-value",
  "state-flag",
  "collection-view",
  "record-view",
  "value-list",
  "binary-control",
  "text-control",
  "numeric-control",
  "multi-choice",
  "editable-collection",
  "record-editor",
  "structured-control",
  "validation-carrier",
  "hydration-source",
  "trigger-binding",
  "repeat-binding",
];

import { describe, it, expect } from "vitest";
import { UI_ROLES, type UiRole } from "@/lib/subid-ui";
import {
  ROLE_MAP,
  ALL_UI_ROLES,
  componentForRole,
  isOmittedRole,
  isReadOnlyRole,
  needsRepeat,
  staticPropsForRole,
} from "@/json-render/catalog/role-map";
import { CATALOG_COMPONENTS } from "@/json-render/catalog/catalog";

describe("role-map: completeness", () => {
  it("ROLE_MAP has an entry for every UiRole", () => {
    for (const role of UI_ROLES) {
      expect(ROLE_MAP[role], `missing ROLE_MAP entry for '${role}'`).toBeDefined();
    }
  });

  it("ALL_UI_ROLES matches UI_ROLES", () => {
    expect(ALL_UI_ROLES.slice().sort()).toEqual([...UI_ROLES].sort());
  });

  it("every UiRole is covered exactly once", () => {
    const mapped = new Set(Object.keys(ROLE_MAP));
    const expected = new Set(UI_ROLES);
    expect(mapped).toEqual(expected);
  });
});

describe("role-map: catalog alignment", () => {
  it("non-omitted roles map to valid catalog component names", () => {
    const catalogSet = new Set(CATALOG_COMPONENTS);

    for (const role of UI_ROLES) {
      const mapping = ROLE_MAP[role];
      if (mapping.omit) continue;

      const component = mapping.component;
      expect(
        component,
        `role '${role}' has omit=false but no component`,
      ).toBeDefined();

      expect(
        catalogSet.has(component!),
        `role '${role}' maps to '${component}' which is not in CATALOG_COMPONENTS`,
      ).toBe(true);
    }
  });

  it("omitted roles have no component", () => {
    const omittedRoles: UiRole[] = [
      "surface",
      "validation-carrier",
      "hydration-source",
      "trigger-binding",
      "repeat-binding",
    ];

    for (const role of omittedRoles) {
      expect(ROLE_MAP[role].omit, `expected '${role}' to be omitted`).toBe(true);
      expect(
        ROLE_MAP[role].component,
        `omitted role '${role}' should not have a component`,
      ).toBeUndefined();
    }
  });
});

describe("role-map: helper functions", () => {
  it("componentForRole returns component or undefined for omitted", () => {
    expect(componentForRole("display-value")).toBe("stateValue");
    expect(componentForRole("state-flag")).toBe("statusDot");
    expect(componentForRole("collection-view")).toBe("streamObject");
    expect(componentForRole("surface")).toBeUndefined();
    expect(componentForRole("validation-carrier")).toBeUndefined();
  });

  it("isOmittedRole identifies omitted roles correctly", () => {
    expect(isOmittedRole("surface")).toBe(true);
    expect(isOmittedRole("validation-carrier")).toBe(true);
    expect(isOmittedRole("hydration-source")).toBe(true);
    expect(isOmittedRole("trigger-binding")).toBe(true);
    expect(isOmittedRole("repeat-binding")).toBe(true);

    expect(isOmittedRole("display-value")).toBe(false);
    expect(isOmittedRole("state-flag")).toBe(false);
    expect(isOmittedRole("numeric-control")).toBe(false);
  });

  it("isReadOnlyRole identifies read-only controls", () => {
    // Read-only controls (mut category, no edit yet)
    expect(isReadOnlyRole("binary-control")).toBe(true);
    expect(isReadOnlyRole("text-control")).toBe(true);
    expect(isReadOnlyRole("numeric-control")).toBe(true);
    expect(isReadOnlyRole("multi-choice")).toBe(true);
    expect(isReadOnlyRole("editable-collection")).toBe(true);
    expect(isReadOnlyRole("record-editor")).toBe(true);
    expect(isReadOnlyRole("structured-control")).toBe(true);

    // Obs roles are not "read-only" in the control sense — they are always read-only
    expect(isReadOnlyRole("display-value")).toBe(false);
    expect(isReadOnlyRole("state-flag")).toBe(false);
    expect(isReadOnlyRole("collection-view")).toBe(false);
  });

  it("needsRepeat identifies collection roles", () => {
    expect(needsRepeat("collection-view")).toBe(true);
    expect(needsRepeat("value-list")).toBe(true);
    expect(needsRepeat("editable-collection")).toBe(true);

    expect(needsRepeat("display-value")).toBe(false);
    expect(needsRepeat("record-view")).toBe(false);
    expect(needsRepeat("surface")).toBe(false);
  });

  it("staticPropsForRole returns static props or empty object", () => {
    expect(staticPropsForRole("numeric-control")).toEqual({
      sub: null,
      variant: null,
      tone: null,
    });
    expect(staticPropsForRole("multi-choice")).toEqual({ format: "raw" });
    expect(staticPropsForRole("binary-control")).toEqual({ tone: null });

    // Roles without static props return empty object
    expect(staticPropsForRole("display-value")).toEqual({});
    expect(staticPropsForRole("surface")).toEqual({});
  });
});

describe("role-map: design constraints", () => {
  it("surface is omitted (becomes route, not element)", () => {
    expect(ROLE_MAP["surface"].omit).toBe(true);
  });

  it("all obs roles (display, state-flag, collection, record, value-list) are not read-only flagged", () => {
    // obs roles are inherently read-only by nature; the readOnly flag is for mut controls
    const obsRoles: UiRole[] = [
      "display-value",
      "state-flag",
      "collection-view",
      "record-view",
      "value-list",
    ];
    for (const role of obsRoles) {
      expect(
        ROLE_MAP[role].readOnly,
        `obs role '${role}' should not have readOnly flag`,
      ).toBeFalsy();
    }
  });

  it("all mut roles are flagged read-only (controls are future work)", () => {
    const mutRoles: UiRole[] = [
      "binary-control",
      "text-control",
      "numeric-control",
      "multi-choice",
      "editable-collection",
      "record-editor",
      "structured-control",
    ];
    for (const role of mutRoles) {
      expect(
        ROLE_MAP[role].readOnly,
        `mut role '${role}' should be read-only in this phase`,
      ).toBe(true);
    }
  });
});

