{"content":"/**
 * Plugin Page Spec Generator
 *
 * Generates a json-render Spec from plugin projections using the role-map
 * to determine component types and props.
 */
import type { Spec } from "@json-render/core";
import type { UiSubidProjection, UiRole } from "@/lib/subid-ui";
import {
  componentForRole,
  isOmittedRole,
  needsRepeat,
  staticPropsForRole,
} from "@/json-render/catalog/role-map";

/**
 * Element definition for building specs.
 */
interface Element {
  type: string;
  props: Record<string, unknown>;
  children?: string[];
  repeat?: {
    over: { $state: string };
    as: string;
  };
}

/**
 * Generate a deterministic element ID following the naming convention.
 * Format: <pluginId>--<fieldId>--<role>
 */
function elementId(pluginId: string, fieldId: string, role: string): string {
  return `${pluginId}--${fieldId}--${role}`;
}

/**
 * Generate a state path for a plugin field.
 * Format: /plugins/<pluginId>/<fieldName>
 */
function statePath(pluginId: string, fieldName: string): { $state: string } {
  return { $state: `/plugins/${pluginId}/${fieldName}` };
}

/**
 * Build props for an element based on its role.
 */
function buildPropsForRole(
  pluginId: string,
  fieldId: string,
  role: UiRole,
): Record<string, unknown> {
  const staticProps = staticPropsForRole(role);
  const path = statePath(pluginId, fieldId);

  switch (role) {
    case "display-value":
    case "text-control":
    case "multi-choice":
      // stateValue: path + label
      return {
        ...staticProps,
        path: path.$state,
        label: fieldId,
      };

    case "state-flag":
      // statusDot: status bound via $state
      return {
        ...staticProps,
        status: path,
      };

    case "numeric-control":
      // statCard: label + value bound via $state
      return {
        ...staticProps,
        label: fieldId,
        value: path,
      };

    case "collection-view":
    case "editable-collection":
      // streamObject: pluginId + member
      return {
        ...staticProps,
        pluginId,
        member: fieldId,
      };

    case "record-view":
    case "record-editor":
    case "structured-control":
      // card: title + optional content
      return {
        ...staticProps,
        title: fieldId,
        subtitle: null,
        tone: null,
        className: null,
      };

    case "value-list":
      // container for list of scalars
      return {
        ...staticProps,
        className: null,
      };

    case "binary-control":
      // pill: text bound via $state
      return {
        ...staticProps,
        text: path,
        variant: null,
      };

    default:
      return { ...staticProps };
  }
}

/**
 * Build an element from a projection.
 */
function buildElement(
  pluginId: string,
  projection: UiSubidProjection,
): Element | null {
  const role = projection.role as UiRole;

  if (isOmittedRole(role)) {
    return null;
  }

  const component = componentForRole(role);
  if (!component) {
    return null;
  }

  const props = buildPropsForRole(pluginId, projection.id, role);

  const element: Element = {
    type: component,
    props,
  };

  // Add repeat block for collection roles
  if (needsRepeat(role)) {
    element.repeat = {
      over: statePath(pluginId, projection.id),
      as: "item",
    };
  }

  return element;
}

/**
 * Generate a json-render Spec from plugin projections.
 *
 * @param pluginId - The plugin identifier
 * @param displayName - Human-readable display name for the page title
 * @param projections - Array of UiSubidProjection from the plugin
 * @returns A valid Spec for json-render
 */
export function generatePluginPageSpec(
  pluginId: string,
  displayName: string,
  projections: UiSubidProjection[],
): Spec {
  const elements: Record<string, Element> = {};
  const childIds: string[] = [];

  // Process each projection
  for (const projection of projections) {
    const role = projection.role as UiRole;

    // Skip omitted roles
    if (isOmittedRole(role)) {
      continue;
    }

    const element = buildElement(pluginId, projection);
    if (!element) {
      continue;
    }

    const id = elementId(pluginId, projection.id, role);
    elements[id] = element;
    childIds.push(id);
  }

  // Create root card element
  const rootId = `${pluginId}--page`;
  elements[rootId] = {
    type: "card",
    props: {
      title: displayName,
      subtitle: null,
      tone: null,
      className: null,
    },
    children: childIds,
  };

  return {
    root: rootId,
    elements,
  } as Spec;
}
"}

{"content":"/**
 * Spec Validator
 *
 * Client-side fast validator for json-render specs.
 * Validates structure and references before rendering.
 */
import type { Spec } from "@json-render/core";
import { CATALOG_COMPONENTS } from "@/json-render/catalog/catalog";

/**
 * Result of spec validation.
 */
export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

/**
 * Check if a value is a $state binding.
 */
function isStateBinding(value: unknown): value is { $state: string } {
  return (
    typeof value === "object" &&
    value !== null &&
    "$state" in value &&
    typeof (value as { $state: unknown }).$state === "string"
  );
}

/**
 * Validate that a $state path starts with /.
 */
function validateStatePath(path: string, context: string): string | null {
  if (!path.startsWith("/")) {
    return `${context}: $state path "${path}" must start with /`;
  }
  return null;
}

/**
 * Recursively find and validate all $state bindings in props.
 */
function validateStateBindings(
  props: Record<string, unknown>,
  elementId: string,
): string[] {
  const errors: string[] = [];

  function traverse(obj: unknown, path: string): void {
    if (isStateBinding(obj)) {
      const error = validateStatePath(obj.$state, `${elementId}.${path}`);
      if (error) {
        errors.push(error);
      }
    } else if (typeof obj === "object" && obj !== null) {
      if (Array.isArray(obj)) {
        obj.forEach((item, index) => traverse(item, `${path}[${index}]`));
      } else {
        for (const [key, value] of Object.entries(obj)) {
          traverse(value, path ? `${path}.${key}` : key);
        }
      }
    }
  }

  traverse(props, "props");
  return errors;
}

/**
 * Validate a generated spec for correctness.
 *
 * Checks:
 * - root field exists and references a valid element ID
 * - Every element has a `type` field matching a CATALOG_COMPONENTS entry
 * - Every `$state` path starts with `/`
 * - children arrays reference existing element IDs
 *
 * @param spec - The Spec to validate
 * @returns ValidationResult with valid flag and any errors
 */
export function validateGeneratedSpec(spec: Spec): ValidationResult {
  const errors: string[] = [];
  const catalogSet = new Set(CATALOG_COMPONENTS);

  // Type assertion for accessing spec properties
  const elements = spec.elements as Record<
    string,
    {
      type?: string;
      props?: Record<string, unknown>;
      children?: string[];
    }
  >;
  const root = spec.root as string;

  // Check root field exists
  if (!root) {
    errors.push("Spec is missing required 'root' field");
    return { valid: false, errors };
  }

  // Check root references a valid element
  if (!elements || typeof elements !== "object") {
    errors.push("Spec is missing required 'elements' field");
    return { valid: false, errors };
  }

  if (!elements[root]) {
    errors.push(`Root element "${root}" does not exist in elements`);
  }

  // Get all element IDs for children validation
  const elementIds = new Set(Object.keys(elements));

  // Validate each element
  for (const [elementId, element] of Object.entries(elements)) {
    // Check type field exists
    if (!element.type) {
      errors.push(`Element "${elementId}" is missing required 'type' field`);
      continue;
    }

    // Check type is in catalog
    if (!catalogSet.has(element.type)) {
      errors.push(
        `Element "${elementId}" has unknown type "${element.type}" not in CATALOG_COMPONENTS`,
      );
    }

    // Validate $state paths in props
    if (element.props && typeof element.props === "object") {
      const stateErrors = validateStateBindings(element.props, elementId);
      errors.push(...stateErrors);
    }

    // Validate children references
    if (element.children) {
      if (!Array.isArray(element.children)) {
        errors.push(`Element "${elementId}" has non-array children field`);
      } else {
        for (const childId of element.children) {
          if (!elementIds.has(childId)) {
            errors.push(
              `Element "${elementId}" references non-existent child "${childId}"`,
            );
          }
        }
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}
"}

