      "test-plugin",
      "Test Plugin",
      onlyOmittedProjections,
    );

    // Should have only the root element
    expect(spec.root).toBe("test-plugin--page");
    const elementCount = Object.keys(spec.elements).length;
    expect(elementCount).toBe(1);

    // Root card should have no children
    const rootElement = spec.elements[spec.root] as { children: string[] };
    expect(rootElement.children).toHaveLength(0);
  });

  it("mixed projections only include non-omitted roles as elements", () => {
    const spec = generatePluginPageSpec(
      "test-plugin",
      "Test Plugin",
      mixedProjections,
    );

    const elements = spec.elements as Record<string, unknown>;

    // Should not have elements for omitted roles
    expect(elements["test-plugin--schema--validation-carrier"]).toBeUndefined();
    expect(elements["test-plugin--surface--surface"]).toBeUndefined();
    expect(elements["test-plugin--hydration--hydration-source"]).toBeUndefined();

    // Should have element for non-omitted role
    expect(elements["test-plugin--message--display-value"]).toBeDefined();
  });
});

describe("generatePluginPageSpec: element ID naming convention", () => {
  it("element IDs follow <pluginId>--<fieldId>--<role> convention", () => {
    const spec = generatePluginPageSpec(
      "my-plugin",
      "My Plugin",
      [
        {
          plugin_id: "my-plugin",
          kind: "field",
          id: "my-field",
          subid: "obs.software.plugin.test.my-field@v1",
          category: "obs",
          role: "display-value",
          element_key: "software.plugin.test.my-field@v1",
        },
      ],
    );

    const elementIds = Object.keys(spec.elements);
    expect(elementIds).toContain("my-plugin--page");
    expect(elementIds).toContain("my-plugin--my-field--display-value");
  });

  it("root element ID is <pluginId>--page", () => {
    const spec = generatePluginPageSpec(
      "custom-plugin",
      "Custom Plugin",
      minimalProjections,
    );

    expect(spec.root).toBe("custom-plugin--page");
  });

  it("all non-root element IDs are deterministic based on projection data", () => {
    const projections: UiSubidProjection[] = [
      {
        plugin_id: "plugin-a",
        kind: "field",
        id: "field-x",
        subid: "obs.software.plugin.test.x@v1",
        category: "obs",
        role: "display-value",
        element_key: "software.plugin.test.x@v1",
      },
      {
        plugin_id: "plugin-a",
        kind: "field",
        id: "field-y",
        subid: "obs.software.plugin.test.y@v1",
        category: "obs",
        role: "state-flag",
        element_key: "software.plugin.test.y@v1",
      },
    ];

    // Generate twice, should produce identical IDs
    const spec1 = generatePluginPageSpec("plugin-a", "Plugin A", projections);
    const spec2 = generatePluginPageSpec("plugin-a", "Plugin A", projections);

    expect(Object.keys(spec1.elements).sort()).toEqual(
      Object.keys(spec2.elements).sort(),
    );
    expect(spec1.root).toBe(spec2.root);
  });
});

describe("generatePluginPageSpec: repeat blocks", () => {
  it("collection roles have repeat blocks", () => {
    const spec = generatePluginPageSpec(
      "test-plugin",
      "Test Plugin",
      projectionsWithCollections,
    );

    const elements = spec.elements as Record<
      string,
      { repeat?: { over: { $state: string }; as: string } }
    >;

    const collectionElement = elements["test-plugin--items--collection-view"];
    expect(collectionElement.repeat).toBeDefined();
    expect(collectionElement.repeat?.over.$state).toBe("/plugins/test-plugin/items");
    expect(collectionElement.repeat?.as).toBe("item");
  });

  it("non-collection roles do not have repeat blocks", () => {
    const spec = generatePluginPageSpec(
      "test-plugin",
      "Test Plugin",
      minimalProjections,
    );

    const elements = spec.elements as Record<
      string,
      { repeat?: unknown }
    >;

    expect(elements["test-plugin--status--display-value"].repeat).toBeUndefined();
    expect(elements["test-plugin--connected--state-flag"].repeat).toBeUndefined();
    expect(elements["test-plugin--count--numeric-control"].repeat).toBeUndefined();
  });
});

describe("validateGeneratedSpec: error detection", () => {
  it("detects missing root element", () => {
    const invalidSpec = {
      root: "missing-root",
      elements: {
        "some-element": { type: "card", props: {} },
      },
    };

    const result = validateGeneratedSpec(invalidSpec as unknown as import("@json-render/core").Spec);
    expect(result.valid).toBe(false);
    expect(result.errors.some((e) => e.includes("missing-root"))).toBe(true);
  });

  it("detects unknown component type", () => {
    const invalidSpec = {
      root: "root",
      elements: {
        root: { type: "unknownComponent", props: {} },
      },
    };

    const result = validateGeneratedSpec(invalidSpec as unknown as import("@json-render/core").Spec);
    expect(result.valid).toBe(false);
    expect(result.errors.some((e) => e.includes("unknownComponent"))).toBe(true);
  });

  it("detects invalid $state paths", () => {
    const invalidSpec = {
      root: "root",
      elements: {
        root: {
          type: "card",
          props: { value: { $state: "no-leading-slash" } },
        },
      },
    };

    const result = validateGeneratedSpec(invalidSpec as unknown as import("@json-render/core").Spec);
    expect(result.valid).toBe(false);
    expect(result.errors.some((e) => e.includes("must start with /"))).toBe(true);
  });

  it("detects missing children references", () => {
    const invalidSpec = {
      root: "root",
      elements: {
        root: {
          type: "card",
          props: {},
          children: ["nonexistent-child"],
        },
      },
    };

    const result = validateGeneratedSpec(invalidSpec as unknown as import("@json-render/core").Spec);
    expect(result.valid).toBe(false);
    expect(result.errors.some((e) => e.includes("nonexistent-child"))).toBe(true);
  });
});
"}

{"content":"//! Context assembler for gallery generation.
//!
//! Gathers baseline context for the inference loop:
//! - Plugin schemas from sealed blobs
//! - Static documentation (access-instructions, catalog, grammar)
//! - Operator guidance from Antigravity chat

use anyhow::{Context as _, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;

/// Role-to-component mapping table for plugin page generation.
/// This is included in the system message when generating a plugin page spec.
pub const ROLE_COMPONENT_TABLE: &str = r#"
| UiRole | Catalog Component | Notes |
|---|---|---|
| surface | (omit) | becomes route, not element |
| display-value | stateValue | |
| state-flag | statusDot | |
| collection-view | streamObject | with repeat |
| record-view | card | |
| value-list | container | with repeat |
| binary-control | pill | read-only |
| text-control | stateValue | read-only |
| numeric-control | statCard | read-only |
| multi-choice | stateValue | format=raw, read-only |
| editable-collection | streamObject | with repeat, read-only |
| record-editor | card | read-only |
| structured-control | card | read-only |
| validation-carrier | (omit) | |
| hydration-source | (omit) | |
| trigger-binding | (omit) | |
| repeat-binding | (omit) | |
"#;

/// Assembled context for a single generation run.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GenerationContext {
    /// Baseline: all plugin schemas from blobs
    pub schemas: Vec<SchemaPayload>,

    /// Static docs: access-instructions.md content
    pub access_instructions: String,

    /// The catalog's own system prompt, from `schemas/json-render/catalog.prompt.md`.
    ///
    /// Output contract, directives, state model and every available component —
    /// generated by the catalog that the renderer and the admission gate both
    /// use, so a model cannot be taught a component the gate will reject. Never
    /// hand-written: see [`crate::catalog_guard`].
    pub catalog_prompt: String,

    /// Universal prompt (vague, goal-oriented)
    pub universal_prompt: String,

    /// Operator guidance from Antigravity chat
    pub operator_guidance: Option<String>,

    /// MCP toggle enabled
    pub mcp_enabled: bool,

    /// Qdrant toggle enabled
    pub qdrant_enabled: bool,

    /// Catalog hash at context assembly time (for freshness checks).
    pub catalog_hash: String,

    /// When set, generation is scoped to this plugin.
    pub target_plugin: Option<TargetPluginContext>,
}

/// Schema payload from a plugin blob.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaPayload {
    /// Plugin name
    pub name: String,

    /// Plugin version
    pub version: String,

    /// Human-readable description
    pub description: Option<String>,

    /// OSCAL category (software, network, system, security, compliance, observability)
    pub category: Option<String>,

    /// State fields with types and constraints
    pub fields: HashMap<String, FieldSchema>,

    /// Available methods
    pub methods: HashMap<String, MethodSchema>,

    /// OSCAL subids for traceability
    pub subids: HashMap<String, String>,

    /// Authoritative UI routes declared by this plugin's `ui_surfaces` field.
    #[serde(default)]
    pub ui_surfaces: UiSurfaceProjection,

    /// Raw schema JSON (for tool responses)
    pub raw_json: serde_json::Value,
}

/// A plugin-owned UI projection. Empty routes mean gallery generation should
/// retain its schema-derived fallback instead of inventing authoritative paths.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct UiSurfaceProjection {
    pub subids: Vec<String>,
    pub routes: Vec<UiSurfaceRoute>,
    pub value_source: Option<String>,
}

impl UiSurfaceProjection {
    pub fn is_authoritative(&self) -> bool {
        !self.subids.is_empty() && !self.routes.is_empty()
    }
}

/// Normalized route plus the original plugin-owned route object.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct UiSurfaceRoute {
    pub path: String,
    pub name: Option<String>,
    pub schema: Option<String>,
    pub raw: serde_json::Value,
}

/// Context for plugin-scoped generation (single plugin page spec)."}

