{"content":"/**
 * Dynamic page spec hook.
 *
 * Returns a json-render Spec for a route:
 *   1. If route is in PAGE_SPECS, return the static spec immediately.
 *   2. Otherwise, find which plugin owns this route via its ui_surfaces.
 *   3. Fetch the plugin schema and generate a spec from ui_projection.
 *   4. Memoize by (route, schemaHash) to avoid re-fetching on navigation.
 *   5. Return emptyState spec if no plugin claims the route.
 */
import { useState, useEffect, useMemo, useRef } from "react";
import type { Spec } from "@json-render/core";
import { PAGE_SPECS } from "@/json-render/pages";
import { useEventStore } from "@/stores/event-store";
import { useBlobCatalog } from "@/hooks/use-blob-catalog";
import { resolveApiBase } from "@/lib/api";
import { generatePluginPageSpec } from "./generate-plugin-page";
import type { UiSubidProjection, UiSurfaceProjection } from "@/lib/subid-ui";
import { isAuthoritative } from "@/lib/subid-ui";

export interface UsePluginPageSpecResult {
  spec: Spec | null;
  loading: boolean;
  error: string | null;
  isStatic: boolean;
}

interface PluginSchemaResponse {
  plugin: string;
  schema_hash?: string;
  schema?: {
    display_name?: string;
    fields?: {
      ui_surfaces?: {
        default?: unknown;
      };
    };
  };
  ui_projection?: UiSubidProjection[];
  ui_surfaces?: UiSurfaceProjection;
}

/** Cache for fetched specs, keyed by plugin + schemaHash. */
const specCache = new Map<string, Spec>();

/**
 * Extract display name from schema or fall back to plugin id.
 */
function getDisplayName(response: PluginSchemaResponse): string {
  return response.schema?.display_name ?? response.plugin;
}

/**
 * Parse ui_surfaces routes from a plugin schema response.
 */
function parseUiSurfaceRoutes(response: PluginSchemaResponse): string[] {
  // Prefer the pre-parsed ui_surfaces projection
  if (response.ui_surfaces && isAuthoritative(response.ui_surfaces)) {
    return response.ui_surfaces.routes.map((r) => r.path);
  }
  // Fall back to parsing from schema fields
  const raw = response.schema?.fields?.ui_surfaces?.default;
  if (!Array.isArray(raw)) return [];
  return raw
    .filter(
      (item): item is { path: string } =>
        item && typeof item === "object" && typeof (item as { path?: unknown }).path === "string",
    )
    .map((item) => item.path);
}

/**
 * Fetch plugin schema from the API.
 */
async function fetchPluginSchema(pluginId: string): Promise<PluginSchemaResponse> {
  const response = await fetch(
    `${resolveApiBase()}/ui-model/plugin-schema/${encodeURIComponent(pluginId)}`,
  );
  if (!response.ok) {
    throw new Error(`Plugin schema fetch failed: HTTP ${response.status}`);
  }
  return response.json() as Promise<PluginSchemaResponse>;
}

/**
 * Find which plugin owns a route by checking ui_surfaces.
 * Returns the plugin id and its schema response, or null if no plugin owns the route.
 */
async function findPluginForRoute(
  route: string,
  pluginIds: string[],
  schemas: Record<string, unknown>,
): Promise<{ pluginId: string; response: PluginSchemaResponse } | null> {
  // First check schemas already in the store
  for (const pluginId of pluginIds) {
    const schema = schemas[pluginId] as PluginSchemaResponse | undefined;
    if (schema) {
      const routes = parseUiSurfaceRoutes(schema);
      if (routes.includes(route)) {
        return { pluginId, response: schema };
      }
    }
  }

  // Fetch schemas for plugins not yet in store
  const fetchPromises = pluginIds
    .filter((id) => !schemas[id])
    .map(async (pluginId) => {
      try {
        const response = await fetchPluginSchema(pluginId);
        const routes = parseUiSurfaceRoutes(response);
        if (routes.includes(route)) {
          return { pluginId, response };
        }
      } catch {
        // Skip plugins that fail to fetch
      }
      return null;
    });

  const results = await Promise.all(fetchPromises);
  return results.find((r): r is NonNullable<typeof r> => r !== null) ?? null;
}

/**
 * Generate an empty state spec for routes with no associated page.
 */
function emptyStateSpec(route: string): Spec {
  return {
    root: "root",
    elements: {
      root: {
        type: "emptyState",
        props: {
          title: "Page Not Found",
          hint: `No page spec or plugin ui_surface claims route: ${route}`,
        },
      },
    },
  };
}

/**
 * Generate a loading spec while fetching plugin data.
 */
function loadingSpec(route: string): Spec {
  return {
    root: "root",
    elements: {
      root: {
        type: "emptyState",
        props: {
          title: "Loading...",
          hint: `Resolving page for ${route}`,
        },
      },
    },
  };
}

/**
 * Hook that returns a Spec for a route.
 *
 * - Static routes from PAGE_SPECS are returned immediately.
 * - Dynamic routes are resolved by finding the plugin that owns the route.
 * - Specs are memoized by route + schemaHash to avoid refetching.
 */
export function usePluginPageSpec(route: string): UsePluginPageSpecResult {
  const { plugins } = useBlobCatalog();
  const schemas = useEventStore((s) => s.schemas);
  const schemaHashes = useEventStore((s) => s.schemaHashes);

  // Check static specs first
  const staticSpec = PAGE_SPECS[route];
  if (staticSpec) {
    return {
      spec: staticSpec,
      loading: false,
      error: null,
      isStatic: true,
    };
  }

  const [spec, setSpec] = useState<Spec | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Track the current fetch to avoid race conditions
  const fetchIdRef = useRef(0);

  // Compute a stable cache key from schema hashes
  const cacheKey = useMemo(() => {
    const hashList = plugins
      .map((id) => schemaHashes[id] ?? "")
      .filter(Boolean)
      .sort()
      .join(",");
    return `${route}:${hashList}`;
  }, [route, plugins, schemaHashes]);

  useEffect(() => {
    let cancelled = false;
    const fetchId = ++fetchIdRef.current;

    async function resolveSpec() {
      // Check cache first
      const cached = specCache.get(cacheKey);
      if (cached) {
        setSpec(cached);
        setLoading(false);
        setError(null);
        return;
      }

      setLoading(true);
      setError(null);

      try {
        const result = await findPluginForRoute(route, plugins, schemas);

        if (cancelled || fetchId !== fetchIdRef.current) return;

        if (!result) {
          // No plugin claims this route
          const emptySpec = emptyStateSpec(route);
          setSpec(emptySpec);
          setLoading(false);
          return;
        }

        const { pluginId, response } = result;
        const projections = response.ui_projection ?? [];
        const displayName = getDisplayName(response);

        const generatedSpec = generatePluginPageSpec(pluginId, displayName, projections);

        // Cache the spec
        specCache.set(cacheKey, generatedSpec);

        if (!cancelled && fetchId === fetchIdRef.current) {
          setSpec(generatedSpec);
          setLoading(false);
        }
      } catch (err) {
        if (!cancelled && fetchId === fetchIdRef.current) {
          setError(err instanceof Error ? err.message : String(err));
          setLoading(false);
        }
      }
    }

    resolveSpec();

    return () => {
      cancelled = true;
    };
  }, [route, plugins, schemas, cacheKey]);

  return {
    spec,
    loading,
    error,
    isStatic: false,
  };
}
"}

{"content":"/**
 * Dynamic navigation hook.
 *
 * Enriches NAV_MANIFEST with entries from plugin ui_surfaces:
 *   1. Start with NAV_MANIFEST (static routes).
 *   2. For each plugin in useBlobCatalog().plugins, check for ui_surfaces in schemas.
 *   3. For each authoritative surface route, add a NavItem to a "Plugins" section.
 *   4. Deduplicate: if route already in NAV_MANIFEST, static wins.
 *   5. Return merged list.
 */
import { useMemo } from "react";
import { NAV_MANIFEST, type NavItem, type NavSection } from "./manifest";
import { useBlobCatalog } from "@/hooks/use-blob-catalog";
import { useEventStore } from "@/stores/event-store";
import type { UiSurfaceProjection, UiSurfaceRoute } from "@/lib/subid-ui";
import { isAuthoritative } from "@/lib/subid-ui";

/** Section name for plugin-contributed nav entries. */
const PLUGINS_SECTION: NavSection = "Plugins";

/** Starting order value for plugin nav entries. */
const PLUGIN_NAV_ORDER_BASE = 100;

/**
 * Schema shape that may contain ui_surfaces.
 */
interface SchemaWithUiSurfaces {
  display_name?: string;
  fields?: {
    ui_surfaces?: {
      default?: unknown;
    };
  };
  ui_surfaces?: UiSurfaceProjection;
}

/**
 * Extract ui_surfaces routes from a plugin schema.
 */
function extractUiSurfaceRoutes(
  pluginId: string,
  schema: unknown,
): Array<{ route: UiSurfaceRoute; pluginId: string }> {
  const schemaObj = schema as SchemaWithUiSurfaces | null;
  if (!schemaObj) return [];

  // Prefer the pre-parsed ui_surfaces projection
  if (schemaObj.ui_surfaces && isAuthoritative(schemaObj.ui_surfaces)) {
    return schemaObj.ui_surfaces.routes.map((route) => ({ route, pluginId }));
  }

  // Fall back to parsing from schema fields
  const raw = schemaObj.fields?.ui_surfaces?.default;
  if (!Array.isArray(raw)) return [];

  return raw
    .filter(
      (item): item is UiSurfaceRoute =>
        item &&
        typeof item === "object" &&
        typeof (item as UiSurfaceRoute).path === "string",
    )
    .map((route) => ({ route, pluginId }));
}

/**
 * Generate a display label for a nav item.
 * Uses route name if available, otherwise derives from path.
 */
function generateNavLabel(route: UiSurfaceRoute, pluginId: string): string {
  if (route.name) return route.name;

  // Derive from path: /plugin-name/page -> Page
  const parts = route.path.split("/").filter(Boolean);
  if (parts.length > 0) {
    const last = parts[parts.length - 1];
    return last.charAt(0).toUpperCase() + last.slice(1).replace(/-/g, " ");
  }

  return pluginId;
}

/**
 * Generate a nav item ID from plugin and route.
 */
function generateNavId(pluginId: string, route: UiSurfaceRoute): string {
  const pathPart = route.path.replace(/^\//, "").replace(/\//g, "-") || "root";
  return `plugin-${pluginId}-${pathPart}`;
}

/**
 * Create a NavItem from a plugin ui_surface route.
 */
function createPluginNavItem(
  pluginId: string,
  route: UiSurfaceRoute,
  order: number,
): NavItem {
  return {
    id: generateNavId(pluginId, route),
    label: generateNavLabel(route, pluginId),
    route: route.path,
    icon: "Package", // Default icon for plugin routes
    section: PLUGINS_SECTION,
    order,
  };
}

/**
 * Hook that returns NavItem[] with dynamic plugin routes merged.
 *
 * - Static NAV_MANIFEST entries take precedence over plugin routes.
 * - Plugin ui_surfaces routes are added to a "Plugins" section.
 * - Deduplication ensures no route appears twice.
 */
export function useDynamicNav(): NavItem[] {
  const { plugins } = useBlobCatalog();
  const schemas = useEventStore((s) => s.schemas);

  return useMemo(() => {
    // Collect static routes for deduplication
    const staticRoutes = new Set(NAV_MANIFEST.map((item) => item.route));

    // Also include aliases in the static routes set
    for (const item of NAV_MANIFEST) {
      if (item.aliases) {
        for (const alias of item.aliases) {
          staticRoutes.add(alias);
        }
      }
    }

    // Collect plugin routes
    const pluginNavItems: NavItem[] = [];
    let orderCounter = PLUGIN_NAV_ORDER_BASE;

    for (const pluginId of plugins) {
      const schema = schemas[pluginId];
      if (!schema) continue;

      const surfaceRoutes = extractUiSurfaceRoutes(pluginId, schema);

      for (const { route } of surfaceRoutes) {
        // Skip if this route is already claimed by static nav
        if (staticRoutes.has(route.path)) continue;

        // Skip if we've already added this route from another plugin
        if (pluginNavItems.some((item) => item.route === route.path)) continue;

        pluginNavItems.push(createPluginNavItem(pluginId, route, orderCounter++));
      }
    }

    // Merge: static manifest first, then plugin items
    return [...NAV_MANIFEST, ...pluginNavItems];
  }, [plugins, schemas]);
}

/**
 * Check if the Plugins section should be visible.
 * Returns true if there are any plugin-contributed nav items.
 */
export function useHasPluginNav(): boolean {
  const navItems = useDynamicNav();
  return navItems.some((item) => item.section === PLUGINS_SECTION);
}
"}

{"content":"/**
 * Route-aware page outlet.
 *
 * Uses the usePluginPageSpec hook to resolve specs:
 *   1. Static PAGE_SPECS win.
 *   2. `/plugins/:id` (not `/plugins` itself) renders the sealed-schema ui_projection.
 *   3. Dynamic plugin routes are resolved from ui_surfaces.
 *   4. Everything else falls through to <Outlet />.
 *
 * Shows a loading state while fetching dynamic specs. Shell chrome remains
 * visible; only the content region shows loading.
 */
import { useMemo } from "react";
import { Outlet, useLocation } from "react-router-dom";
import { Renderer } from "@json-render/react";
import { useJsonRender } from "./JsonRenderProvider";
import { PAGE_SPECS } from "@/json-render/pages";
import { ProjectedPluginPage } from "./ProjectedPluginPage";
import { usePluginPageSpec } from "@/json-render/spec-gen";

export { PAGE_SPECS };

function pluginIdFromPath(pathname: string): string | null {
  const match = pathname.match(/^\/plugins\/([^/]+)\/?$/);
  if (!match) return null;
  try {
    return decodeURIComponent(match[1]);
  } catch {
    return match[1];
  }
}

/**
 * Loading spec for the content region.
 */
function loadingSpec(route: string) {
  return {
    root: "root",
    elements: {
      root: {
        type: "emptyState",
        props: {
          title: "Loading...",
          hint: `Resolving page for ${route}`,
        },
      },
    },
  };
}

/**
 * Error spec for the content region.
 */
function errorSpec(error: string) {
  return {
    root: "root",
    elements: {
      root: {
        type: "statusBanner",
        props: {
          title: "Error",
          message: error,
          tone: "danger",
        },
      },
    },
  };
}

export function PageSpecOutlet() {
  const { pathname } = useLocation();
  const { registry } = useJsonRender();

  // Use the dynamic hook for spec resolution
  const { spec, loading, error, isStatic } = usePluginPageSpec(pathname);

  // Special case: /plugins/:id routes use ProjectedPluginPage
  const pluginId = useMemo(() => {
    // Only check for plugin ID if this isn't a static route
    if (isStatic) return null;
    return pluginIdFromPath(pathname);
  }, [pathname, isStatic]);

  // Static spec from PAGE_SPECS
  if (isStatic && spec) {
    return <Renderer spec={spec} registry={registry} />;
  }

  // /plugins/:id routes use ProjectedPluginPage directly
  if (pluginId) {
    return <ProjectedPluginPage pluginId={pluginId} />;
  }

  // Show loading state while fetching dynamic spec
  if (loading) {
    return <Renderer spec={loadingSpec(pathname)} registry={registry} />;
  }

  // Show error state if fetch failed
  if (error) {
    return <Renderer spec={errorSpec(error)} registry={registry} />;
  }

  // Dynamic spec from plugin ui_surfaces
  if (spec) {
    return <Renderer spec={spec} registry={registry} />;
  }

  // Fallback to React Router outlet
  return <Outlet />;
}
"}

{"content":"/**
 * ShellRenderer — mounts the shell spec.
 *
 * This is the whole application chrome. It replaces `AppShell.tsx`: the
 * markup now comes from `buildShellSpec()` and the registry, and `children`
 * (the router) is injected into the spec's `contentRegion` slot.
 *
 * Navigation is dynamic: the sidebar includes both static NAV_MANIFEST entries
 * and plugin-contributed routes from ui_surfaces. Use `useDynamicNav` to
 * automatically merge these sources.
 */
import { useMemo, type ReactNode } from "react";
import { Renderer } from "@json-render/react";
import {
  JsonRenderProvider,
  useJsonRender,
} from "@/json-render/runtime/JsonRenderProvider";
import { CONTENT_SLOT } from "@/json-render/runtime/slots";
import { ALLOW_ALL, type CapabilitySet } from "@/json-render/navigation/capabilities";
import { NAV_MANIFEST, type NavItem } from "@/json-render/navigation/manifest";
import { useDynamicNav } from "@/json-render/navigation/use-dynamic-nav";
import { buildShellSpec, DEFAULT_CHROME, type ShellChrome } from "./shellSpec";

function ShellSpecRenderer({ chrome }: { chrome: ShellChrome }) {
  const { registry, capabilities, manifest } = useJsonRender();
  // Capability filtering happens at build time: a filtered-out nav entry is
  // absent from the spec, not merely hidden.
  const spec = useMemo(
    () => buildShellSpec(manifest, capabilities, chrome),
    [manifest, capabilities, chrome],
  );
  return <Renderer spec={spec} registry={registry} />;
}

/**
 * Inner component that uses dynamic navigation.
 * Only uses the hook when no explicit manifest is provided.
 */
function DynamicNavShell({
  children,
  capabilities = ALLOW_ALL,
  chrome = DEFAULT_CHROME,
}: {
  children: ReactNode;
  capabilities?: CapabilitySet;
  chrome?: ShellChrome;
}) {
  // Get dynamic navigation (merges static manifest with plugin ui_surfaces)
  const dynamicNavItems = useDynamicNav();

  return (
    <JsonRenderProvider
      manifest={dynamicNavItems}
      capabilities={capabilities}
      slots={{ [CONTENT_SLOT]: children }}
    >
      <ShellSpecRenderer chrome={chrome} />
    </JsonRenderProvider>
  );
}

/**
 * Static shell component that uses the provided manifest without dynamic nav.
 * Used when an explicit manifest is passed, or for testing.
 */
function StaticShell({
  children,
  manifest,
  capabilities = ALLOW_ALL,
  chrome = DEFAULT_CHROME,
}: {
  children: ReactNode;
  manifest: NavItem[];
  capabilities?: CapabilitySet;
  chrome?: ShellChrome;
}) {
  return (
    <JsonRenderProvider
      manifest={manifest}
      capabilities={capabilities}
      slots={{ [CONTENT_SLOT]: children }}
    >
      <ShellSpecRenderer chrome={chrome} />
    </JsonRenderProvider>
  );
}

export function ShellRenderer({
  children,
  manifest,
  capabilities = ALLOW_ALL,
  chrome = DEFAULT_CHROME,
}: {
  children: ReactNode;
  /** Pass explicit manifest to disable dynamic nav. Defaults to useDynamicNav(). */
  manifest?: NavItem[];
  capabilities?: CapabilitySet;
  chrome?: ShellChrome;
}) {
  // When an explicit manifest is provided, use it directly without dynamic nav.
  // This avoids unnecessary hook calls and test complications.
  if (manifest) {
    return (
      <StaticShell
        manifest={manifest}
        capabilities={capabilities}
        chrome={chrome}
      >
        {children}
      </StaticShell>
    );
  }

  // Default: use dynamic navigation
  return (
    <DynamicNavShell capabilities={capabilities} chrome={chrome}>
      {children}
    </DynamicNavShell>
  );
}
"}

