A React hook that returns a Spec for a route:
```ts
import { useState, useEffect, useMemo } from "react";
import type { Spec } from "@json-render/core";
import { PAGE_SPECS } from "@/json-render/pages";
import { useEventStore } from "@/stores/event-store";
import { useBlobCatalog } from "@/hooks/use-blob-catalog";
import { resolveApiBase } from "@/lib/api";
import { generatePluginPageSpec } from "./generate-plugin-page";
import type { UiSubidProjection, UiSurfaceProjection } from "@/lib/subid-ui";
import { isAuthoritative } from "@/lib/subid-ui";

export interface UsePluginPageSpecResult {
  spec: Spec | null;
  loading: boolean;
  error: string | null;
  isStatic: boolean;
}

export function usePluginPageSpec(route: string): UsePluginPageSpecResult
```

Logic:
1. If route is in PAGE_SPECS, return { spec: PAGE_SPECS[route], loading: false, error: null, isStatic: true }
2. Otherwise, find which plugin owns this route via its ui_surfaces
3. Fetch GET /api/ui-model/plugin-schema/:plugin to get ui_projection (UiSubidProjection[])
4. Call generatePluginPageSpec(pluginId, displayName, projections)
5. Memoize by (route, schemaHash) - schemaHash from useEventStore.schemaHashes
6. Return emptyState spec if no plugin claims the route

